for(const row of scope.querySelectorAll('[data-lorebook-entry-row-id]')){const drawer=row.querySelector(':scope>div.border-t');if(!drawer||!drawer.querySelector('textarea,input'))continue;if(!drawer.querySelector('.mft-lore-guide')){const guide=el('details','mft-lore-guide');guide.append(el('summary','','처음 쓰는 로어북 · 사용 순서'),el('p','','① 주요 키워드에 대화에서 찾을 단어를 넣으세요. 예: 학교, 교실'),el('p','','② 내용에는 AI가 참고할 설정을 쓰세요. 예: 학교는 바닷가 마을에 있습니다.'),el('p','','③ 항목을 켜면 조건에 맞을 때 내용을 참고합니다. 보조 키워드와 고급 설정은 필요할 때만 사용하세요.'));drawer.prepend(guide);nativeUiAdditions.add(guide);}const help=[['주요 키워드','대화에 이 단어가 나오면 내용을 참고합니다. 쉼표로 나누거나 Enter로 추가하세요.'],['Primary keys','Words to look for in chat. Add each word with Enter.'],['보조 키워드','주요 키워드와 함께 검사할 추가 조건입니다. 필요 없으면 비워 두세요.'],['설명','목록에서 알아보기 위한 짧은 메모입니다. 실제 설정은 내용에 적으세요.'],['내용','조건이 맞을 때 AI에게 전달할 설정입니다.'],['결정','AI에게 추가 판단을 맡기는 옵션입니다. 처음에는 사용 안 함으로 두세요.']];for(const label of drawer.querySelectorAll('label,div[class~="mb-1.5"][class~="font-medium"]')){const text=label.textContent.trim();const found=help.find(([key])=>text.startsWith(key));if(found&&!label.nextElementSibling?.classList.contains('mft-field-help')){const hint=el('p','mft-field-help',found[1]);label.after(hint);nativeUiAdditions.add(hint);}}for(const b of drawer.querySelectorAll('button')){const hints={'AND Any':'보조 키워드 중 하나 이상 있어야 적용','AND All':'보조 키워드가 모두 있어야 적용','NOT Any':'보조 키워드가 하나라도 있으면 제외','NOT All':'보조 키워드가 모두 있으면 제외'};if(hints[b.textContent.trim()]&&!b.hasAttribute('data-mft-hint')){b.dataset.mftOldTitle=b.getAttribute('title')||'';b.dataset.mftHint='';b.title=hints[b.textContent.trim()];}}}
