function bindNativeUi(){nativeUiObserver?.disconnect();nativeUiRoots=[];if(disposed||root.dataset.native!=='true'||routeIntent==='chat')return;const candidates=[...document.querySelectorAll('[data-component="CenterContent"],.mari-editor-shell,[data-panel-key="characters"],[data-panel-key="personas"],[data-panel-key="presets"],[data-panel-key="lorebooks"],[data-panel-key="settings"]')].filter(visible);nativeUiRoots=candidates.filter(n=>!candidates.some(p=>p!==n&&p.contains(n)));if(!nativeUiObserver)nativeUiObserver=new MutationObserver(records=>{if(document.hidden||nativeUiQueued||!records.some(r=>!r.target.closest?.('.mft-tag-list')&&!r.target.parentElement?.closest('.mft-tag-list')&&(r.type==='characterData'||[...r.addedNodes,...r.removedNodes].some(n=>!(n instanceof Element)||!n.matches('.mft-lore-guide,.mft-field-help,.mft-tag-list,.mft-settings-fold,.mft-settings-index')))))return;const changed=new Set();for(const r of records){const parent=r.target.nodeType===1?r.target:r.target.parentElement;if(parent?.closest('.mft-lore-guide,.mft-field-help,.mft-tag-list,.mft-settings-fold,.mft-settings-index'))continue;const row=parent?.closest('[data-lorebook-entry-row-id],[data-touch-drag-card="character"]');if(row)changed.add(row.parentElement);for(const n of r.addedNodes)if(n instanceof Element&&!n.matches('.mft-lore-guide,.mft-field-help,.mft-tag-list,.mft-settings-fold,.mft-settings-index'))changed.add(n.parentElement||n);}if(!changed.size)return;nativeUiQueued=true;queueMicrotask(()=>{nativeUiQueued=false;enhanceNativeUi([...changed].filter(n=>n?.isConnected));});});enhanceNativeUi();}
async function collectExistingTags(kind){const old=tagOptionCache.get(kind);if(old&&Date.now()-old.time<60000)return old.tags;const cached=queryCache?.find?.({queryKey:kind==='persona'?['personas']:['characters','list'],exact:true})?.state?.data;const tags=new Set();const collect=row=>{let data=row.data;try{if(typeof data==='string')data=JSON.parse(data);}catch{data=null;}let values=row.tags||data?.data?.tags||data?.tags||row.parsed?.tags||[];try{if(typeof values==='string')values=JSON.parse(values);}catch{values=[];}if(!Array.isArray(values))values=[];for(const tag of values)if(typeof tag==='string'&&tag.trim())tags.add(tag.trim());};if(Array.isArray(cached)){cached.forEach(collect);const sorted=[...tags].sort((a,b)=>a.localeCompare(b));tagOptionCache.set(kind,{time:Date.now(),tags:sorted});return sorted;}const controller=new AbortController();tagFetchControllers.set(kind,controller);const list=kind==='persona'?'/characters/personas/list':'/characters/catalog';for(let offset=0;;offset+=100){const page=await jsonRequest(list+'?'+new URLSearchParams({limit:'100',offset:String(offset)}),'GET',undefined,controller.signal);if(disposed)return [];const rows=Array.isArray(page)?page:page.items||[];rows.forEach(collect);if(!page.hasMore||!rows.length)break;}const sorted=[...tags].sort((a,b)=>a.localeCompare(b));tagOptionCache.set(kind,{time:Date.now(),tags:sorted});return sorted;}
